/**
 * Helper to retrieve translated meaning and example sentence for a conjunction in the active language.
 * Falls back to English if the active language is not available, then Danish.
 */
export function getConjunctionWordTranslation(wordKey, lang = null) {
  let targetLang = lang;
  if (!targetLang && typeof window !== 'undefined') {
    const hashSegments = window.location.hash.split('/');
    if (hashSegments.length > 1 && hashSegments[1]) {
      targetLang = hashSegments[1];
    } else {
      targetLang = localStorage.getItem('appLang') || 'da';
    }
  }
  if (!targetLang) targetLang = 'da';

  let entry = konjunktionerWordTranslations[wordKey];
  if (!entry) {
    // Search by id or flow_ prefix or baseWord
    const foundKey = Object.keys(konjunktionerWordTranslations).find(k => {
      const item = konjunktionerWordTranslations[k];
      return item.id === wordKey || item.baseWord === wordKey || k === 'flow_' + wordKey;
    });
    if (foundKey) entry = konjunktionerWordTranslations[foundKey];
  }

  if (!entry) return null;

  const trans = entry[targetLang] 
    || (targetLang !== 'da' ? entry['en'] : null) 
    || entry['da'];

  if (!trans) return null;

  return {
    meaning: trans.meaning,
    word: trans.meaning, // Alias for views expecting .word
    sentence: trans.sentence
  };
}
